let selectedExam=null,selectedCategory='Science',selectedSubject=null,selectedSubjects=[],quiz=null,timerInterval=null,authMode='signup';
const $=id=>document.getElementById(id);const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function targetQuestionCount(subject){return ['English Language','English Studies','Use of English','Mathematics'].includes(subject)?60:50;}
function getBank(subject){return BANK[subject]||FALLBACKS[subject]||[Q('Which approach is most helpful when learning a new subject?',['Read carefully, practise, and review mistakes','Guess every answer without reading','Avoid asking questions','Never check your work'],0,'Careful study, practice, and reviewing mistakes support learning.'),Q('What should you do if you are unsure of an answer?',['Read the question carefully and eliminate unlikely options','Close the practice immediately','Choose without reading','Leave every question blank'],0,'Read carefully and use evidence to narrow the options.'),Q('Why is regular practice useful?',['It helps build understanding and recall','It guarantees every exam question will repeat','It removes the need to study','It always gives a perfect score'],0,'Regular practice strengthens understanding and recall.'),Q('Which is a useful study habit?',['Review errors and learn why they happened','Ignore feedback','Study only at the last minute','Never take breaks'],0,'Reviewing errors helps identify gaps and improve.'),Q('Before submitting a test, it is useful to ___.',['check your answers if time allows','delete your work','avoid reading questions','change every answer randomly'],0,'Use remaining time to review answers carefully.')];}
function renderExams(){ $('examGrid').innerHTML=Object.entries(EXAMS).map(([name,e])=>`<button class="exam-card ${selectedExam===name?'selected':''}" data-exam="${escapeHTML(name)}"><span class="exam-symbol">${e.symbol}</span><b>${escapeHTML(name)}</b><small>${escapeHTML(e.desc)}</small><span class="choose-label">${selectedExam===name?'Selected ✓':'Choose exam →'}</span></button>`).join('');document.querySelectorAll('[data-exam]').forEach(b=>b.addEventListener('click',()=>chooseExam(b.dataset.exam)));}
function requiredSubjectCount(){return ['WAEC','NECO'].includes(selectedExam)?9:selectedExam==='JAMB / UTME'?5:null;}
function chooseExam(name){selectedExam=name;selectedCategory=Object.keys(EXAMS[name].groups)[0];selectedSubject=null;selectedSubjects=[];if(name==='JAMB / UTME')selectedSubjects.push('Use of English');renderExams();$('selectedExamTitle').textContent=name;$('selectedExamDesc').textContent=EXAMS[name].desc;$('startPractice').disabled=true;renderCategories();renderSubjects();}
function renderCategories(){const groups=EXAMS[selectedExam].groups;$('categoryTabs').innerHTML=Object.keys(groups).map(g=>`<button class="category-tab ${selectedCategory===g?'active':''}" data-category="${escapeHTML(g)}">${escapeHTML(g)}</button>`).join('');document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{selectedCategory=b.dataset.category;renderCategories();renderSubjects();}));}
function renderSubjects(){if(!selectedExam)return;const subs=EXAMS[selectedExam].groups[selectedCategory]||[];const limit=requiredSubjectCount();$('subjectGrid').innerHTML=subs.map(s=>{const chosen=selectedSubjects.includes(s),practice=selectedSubject===s;return `<div class="subject-choice-wrap"><button type="button" class="subject-option ${chosen?'selected':''} ${practice?'practice-selected':''}" data-subject="${escapeHTML(s)}" aria-pressed="${practice}"><span class="subject-check">${chosen?'✓':'+'}</span><span><b>${escapeHTML(s)}</b><small>${chosen?(practice?'Selected · ready to practise':'In your combination'):'Add to combination'} · ${targetQuestionCount(s)} questions</small></span></button>${chosen&&!(selectedExam==='JAMB / UTME'&&s==='Use of English')?`<button type="button" class="subject-remove" data-remove-subject="${escapeHTML(s)}" aria-label="Remove ${escapeHTML(s)}">Remove</button>`:''}</div>`}).join('');
$('combinationHelp').textContent=limit?`${selectedSubjects.length} of ${limit} subjects selected${selectedExam==='JAMB / UTME'?' (Use of English is compulsory, plus four other subjects).':''} You can select subjects across Science, Arts and Commercial tabs. Click a selected subject to remove it; use Practise this subject to start.`:'Choose a subject to practise. Use the category tabs to browse subjects.';
$('subjectCount').textContent=limit?`${selectedSubjects.length} / ${limit} subjects`: `${selectedSubjects.length} selected`;
$('startPractice').disabled=!selectedSubject||!selectedSubjects.includes(selectedSubject);
$('startPractice').textContent=selectedSubject?'Practise '+selectedSubject+' →':'Select a subject to practise';
$('questionCount').value=String(selectedSubject?targetQuestionCount(selectedSubject):60);
$('questionCountNote').textContent=selectedSubject?`${targetQuestionCount(selectedSubject)} questions per session for ${selectedSubject}.`:'English and Mathematics: 60 questions. Other subjects: 50 questions.';
document.querySelectorAll('[data-subject]').forEach(b=>b.addEventListener('click',()=>{const subject=b.dataset.subject;if(!selectedSubjects.includes(subject)){if(limit&&selectedSubjects.length>=limit){$('combinationHelp').textContent=`You have selected all ${limit} subjects. Remove one selected subject before adding another.`;return;}selectedSubjects.push(subject);}selectedSubject=subject;if(selectedExam==='JAMB / UTME'&&!selectedSubjects.includes('Use of English'))selectedSubjects.unshift('Use of English');$('startPractice').disabled=!selectedSubject||!selectedSubjects.includes(selectedSubject);renderSubjects();}));document.querySelectorAll('[data-remove-subject]').forEach(b=>b.addEventListener('click',()=>{const subject=b.dataset.removeSubject;selectedSubjects=selectedSubjects.filter(s=>s!==subject);if(selectedSubject===subject)selectedSubject=null;$('startPractice').disabled=!selectedSubject||!selectedSubjects.includes(selectedSubject);renderSubjects();}));}
function shuffled(a){return [...a].sort(()=>Math.random()-.5)}
function startPractice(){if(!selectedExam||!selectedSubject)return;const base=shuffled(getBank(selectedSubject));const count=targetQuestionCount(selectedSubject);const bank=[];for(let i=0;i<count;i++){const source=base[i%base.length];bank.push(source);}if(base.length<count){$('questionCountNote').textContent='This starter question bank currently contains '+base.length+' authored questions for '+selectedSubject+'. The requested session length is '+count+'; remaining slots repeat shuffled practice items until a fuller, verified question bank is added.';}quiz={exam:selectedExam,subject:selectedSubject,questions:bank,index:0,answers:Array(count).fill(null),seconds:count*60,startedAt:Date.now()};$('quizExamLabel').textContent=selectedExam.toUpperCase()+' • '+selectedCategory.toUpperCase();$('quizTitle').textContent=selectedSubject;$('calculator').hidden=true;$('calcDisplay').value='';$('quizModal').hidden=false;renderQuestion();startTimer();}
function renderQuestion(){if(!quiz)return;const q=quiz.questions[quiz.index];$('questionCounter').textContent=`Question ${quiz.index+1} of ${quiz.questions.length}`;$('answeredCounter').textContent=`${quiz.answers.filter(a=>a!==null).length} answered`;$('quizProgressBar').style.width=`${(quiz.index+1)/quiz.questions.length*100}%`;$('questionArea').innerHTML=`<p class="question-instruction">Choose one answer.</p><h3 class="question-text">${quiz.index+1}. ${escapeHTML(q.q)}</h3><div class="answer-options">${q.opts.map((o,i)=>`<button class="answer-option ${quiz.answers[quiz.index]===i?'selected':''}" data-answer="${i}"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${escapeHTML(o)}</span></button>`).join('')}</div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{quiz.answers[quiz.index]=Number(b.dataset.answer);renderQuestion();}));$('prevQuestion').disabled=quiz.index===0;$('prevQuestion').style.opacity=quiz.index===0?'.45':'1';$('nextQuestion').textContent=quiz.index===quiz.questions.length-1?'Last question':'Next →';$('questionDots').innerHTML=quiz.answers.map((a,i)=>`<button class="question-dot ${a!==null?'answered':''} ${i===quiz.index?'current':''}" data-jump="${i}" aria-label="Go to question ${i+1}"></button>`).join('');document.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click',()=>{quiz.index=Number(b.dataset.jump);renderQuestion();}));}
function startTimer(){clearInterval(timerInterval);updateTimer();timerInterval=setInterval(()=>{if(!quiz)return;quiz.seconds--;updateTimer();if(quiz.seconds<=0){clearInterval(timerInterval);finishQuiz(true);}},1000)}function updateTimer(){const s=Math.max(0,quiz?.seconds||0);$('quizTimer').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');if(s<60)$('quizTimer').style.color='var(--danger)';else $('quizTimer').style.color='';}
function finishQuiz(auto=false){if(!quiz)return;clearInterval(timerInterval);const current=quiz;const correct=current.questions.filter((q,i)=>current.answers[i]===q.ans).length;const answered=current.answers.filter(a=>a!==null).length;const wrong=answered-correct;const pct=Math.round(correct/current.questions.length*100);$('quizModal').hidden=true;$('resultModal').hidden=false;$('resultTitle').textContent=pct>=80?'Excellent work!':pct>=50?'Good effort — keep going!':'Keep practising — you can improve!';$('resultSubtitle').textContent=(auto?'Time ended. ':'')+`${current.exam} · ${current.subject}`;$('scorePercent').textContent=pct+'%';$('scoreFraction').textContent=`${correct} / ${current.questions.length} correct`;$('resultCorrect').textContent=correct;$('resultWrong').textContent=wrong;$('resultSkipped').textContent=current.questions.length-answered;$('answerReview').innerHTML='<h3>Answer review</h3>'+current.questions.map((q,i)=>{const a=current.answers[i],ok=a===q.ans;return `<div class="review-item"><b>${i+1}. ${escapeHTML(q.q)}</b><p class="${ok?'correct':'incorrect'}">${a===null?'Not answered':ok?'Correct':'Your answer: '+escapeHTML(q.opts[a])}</p><p><strong>Correct answer:</strong> ${escapeHTML(q.opts[q.ans])}</p><p>${escapeHTML(q.why)}</p></div>`}).join('');saveResult({exam:current.exam,subject:current.subject,correct,total:current.questions.length,percent:pct,date:new Date().toISOString()});quiz=null;renderHistory();}
function saveResult(r){const hist=JSON.parse(localStorage.getItem('gh_history')||'[]');hist.unshift(r);localStorage.setItem('gh_history',JSON.stringify(hist.slice(0,50)));}
function renderHistory(){const hist=JSON.parse(localStorage.getItem('gh_history')||'[]');$('totalSessions').textContent=hist.length;$('averageScore').textContent=hist.length?Math.round(hist.reduce((s,h)=>s+h.percent,0)/hist.length)+'%':'—';$('bestScore').textContent=hist.length?Math.max(...hist.map(h=>h.percent))+'%':'—';$('historyList').innerHTML=hist.length?hist.slice(0,8).map(h=>`<div class="history-item"><div><b>${escapeHTML(h.exam)} · ${escapeHTML(h.subject)}</b><small>${new Date(h.date).toLocaleString()} · ${h.correct}/${h.total} correct</small></div><span class="history-score">${h.percent}%</span></div>`).join(''):'<p class="empty-state">Your completed sessions will appear here.</p>';}
function openAuth(){ $('authModal').hidden=false;$('authMessage').textContent='';$('authMessage').className='form-message';$('authName').focus();}function closeAuth(){ $('authModal').hidden=true;}function setAuthMode(mode){authMode=mode;document.querySelectorAll('.auth-tab').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('authTitle').textContent=mode==='signup'?'Create your learning profile':'Welcome back';$('authSubmit').textContent=mode==='signup'?'Create profile':'Sign in';$('authName').placeholder=mode==='signup'?'Enter your name':'Name used for this profile';$('authMessage').textContent='';}
function submitAuth(e){e.preventDefault();const name=$('authName').value.trim(),email=$('authEmail').value.trim().toLowerCase(),password=$('authPassword').value;if(!name||password.length<4){showAuthMessage('Enter your name and a password of at least 4 characters.','error');return}let users=JSON.parse(localStorage.getItem('gh_demo_users')||'[]');if(authMode==='signup'){if(users.some(u=>u.name.toLowerCase()===name.toLowerCase())){showAuthMessage('A profile with this name already exists on this browser. Choose Sign in or use another name.','error');return}users.push({name,email,password});localStorage.setItem('gh_demo_users',JSON.stringify(users));localStorage.setItem('gh_profile',JSON.stringify({name,email}));showAuthMessage('Profile created on this device. Welcome, '+name+'!');setTimeout(()=>{closeAuth();updateProfileButton()},700)}else{const user=users.find(u=>u.name.toLowerCase()===name.toLowerCase()&&u.password===password);if(!user){showAuthMessage('Profile not found or password does not match on this browser.','error');return}localStorage.setItem('gh_profile',JSON.stringify({name:user.name,email:user.email}));showAuthMessage('Signed in. Welcome back, '+user.name+'!');setTimeout(()=>{closeAuth();updateProfileButton()},700)}}function showAuthMessage(t,type=''){ $('authMessage').textContent=t;$('authMessage').className='form-message '+type;}
function updateProfileButton(){const profile=JSON.parse(localStorage.getItem('gh_profile')||'null');$('openAuth').textContent=profile?profile.name.split(' ')[0]:'Sign in';$('openAuth').title=profile?'Signed in on this browser. Click to switch profile.':'Sign in or create a profile';}
function calculate(expr){
 if(!expr||!/^[0-9+\-*/().\s]+$/.test(expr))return 'Error';
 try{
  const tokens=expr.match(/\d*\.?\d+|[()+\-*/]/g)||[];let pos=0;
  if(tokens.join('').replace(/\s/g,'')!==expr.replace(/\s/g,''))return 'Error';
  function factor(){const t=tokens[pos++];if(t==='+')return factor();if(t==='-')return -factor();if(t==='('){const v=sum();if(tokens[pos++]!==')')throw Error('parenthesis');return v;}if(t===undefined||!/^\d*\.?\d+$/.test(t))throw Error('number');return Number(t);}
  function term(){let v=factor();while(tokens[pos]==='*'||tokens[pos]==='/'){const op=tokens[pos++],n=factor();if(op==='/'&&n===0)throw Error('divide by zero');v=op==='*'?v*n:v/n;}return v;}
  function sum(){let v=term();while(tokens[pos]==='+'||tokens[pos]==='-'){const op=tokens[pos++],n=term();v=op==='+'?v+n:v-n;}return v;}
  const val=sum();if(pos!==tokens.length||!Number.isFinite(val))return 'Error';return String(Math.round((val+Number.EPSILON)*1e8)/1e8);
 }catch{return 'Error'}
}
$('startPractice').addEventListener('click',startPractice);$('prevQuestion').addEventListener('click',()=>{if(quiz&&quiz.index>0){quiz.index--;renderQuestion()}});$('nextQuestion').addEventListener('click',()=>{if(!quiz)return;if(quiz.index<quiz.questions.length-1){quiz.index++;renderQuestion()}else{const unanswered=quiz.answers.filter(a=>a===null).length;if(unanswered&&!confirm(`You have ${unanswered} unanswered question(s). Submit anyway?`))return;finishQuiz(false)}});$('submitQuiz').addEventListener('click',()=>{if(!quiz)return;const unanswered=quiz.answers.filter(a=>a===null).length;if(unanswered&&!confirm(`You have ${unanswered} unanswered question(s). Submit anyway?`))return;finishQuiz(false)});$('calculatorToggle').addEventListener('click',()=>{const panel=$('calculator');panel.hidden=!panel.hidden;$('calculatorToggle').setAttribute('aria-expanded',String(!panel.hidden));$('calculatorToggle').textContent=panel.hidden?'▦ Calculator':'▦ Hide calculator';if(!panel.hidden){$('calcDisplay').focus();panel.scrollIntoView({block:'nearest',behavior:'smooth'});}});$('calculator').addEventListener('click',e=>{const b=e.target.closest('[data-calc]');if(!b)return;e.preventDefault();const key=b.dataset.calc,display=$('calcDisplay');if(key==='clear')display.value='';else if(key==='back')display.value=display.value.slice(0,-1);else if(key==='equals')display.value=calculate(display.value);else if(/^[0-9+\-*/().]$/.test(key))display.value+=key;});document.addEventListener('keydown',e=>{if($('calculator').hidden||$('quizModal').hidden)return;if(/^[0-9+\-*/().]$/.test(e.key))$('calcDisplay').value+=e.key;else if(e.key==='Enter')$('calcDisplay').value=calculate($('calcDisplay').value);else if(e.key==='Backspace')$('calcDisplay').value=$('calcDisplay').value.slice(0,-1);else if(e.key==='Escape')$('calcDisplay').value='';});$('closeAuth').addEventListener('click',closeAuth);$('openAuth').addEventListener('click',openAuth);$('authForm').addEventListener('submit',submitAuth);document.querySelectorAll('.auth-tab').forEach(b=>b.addEventListener('click',()=>setAuthMode(b.dataset.mode)));$('authModal').addEventListener('click',e=>{if(e.target===$('authModal'))closeAuth()});$('closeResult').addEventListener('click',()=>{$('resultModal').hidden=true});$('finishResult').addEventListener('click',()=>{$('resultModal').hidden=true;document.querySelector('#exams').scrollIntoView({behavior:'smooth'})});$('retryQuiz').addEventListener('click',()=>{$('resultModal').hidden=true;if(selectedExam&&selectedSubject)startPractice()});$('resultModal').addEventListener('click',e=>{if(e.target===$('resultModal'))$('resultModal').hidden=true});$('themeToggle').addEventListener('click',()=>{document.body.classList.toggle('dark');localStorage.setItem('gh_theme',document.body.classList.contains('dark')?'dark':'light');$('themeToggle').textContent=document.body.classList.contains('dark')?'☀':'☾'});$('menuToggle').addEventListener('click',()=> $('mainNav').classList.toggle('open'));document.querySelectorAll('#mainNav a').forEach(a=>a.addEventListener('click',()=> $('mainNav').classList.remove('open')));$('clearHistory').addEventListener('click',()=>{if(confirm('Clear saved practice history from this browser?')){localStorage.removeItem('gh_history');renderHistory()}});document.querySelectorAll('[data-exam-link]').forEach(a=>a.addEventListener('click',()=>chooseExam(a.dataset.examLink)));$('year').textContent=new Date().getFullYear();if(localStorage.getItem('gh_theme')==='dark'){document.body.classList.add('dark');$('themeToggle').textContent='☀'}renderExams();renderHistory();updateProfileButton();

