let growthHubInstallPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();growthHubInstallPrompt=e;const b=document.getElementById('installApp');if(b)b.hidden=false;});const installButton=document.getElementById('installApp');if(installButton){installButton.addEventListener('click',async()=>{if(!growthHubInstallPrompt){alert('To install, open your browser menu and choose Install app or Add to Home Screen.');return;}growthHubInstallPrompt.prompt();await growthHubInstallPrompt.userChoice;growthHubInstallPrompt=null;installButton.hidden=true;});}
